mkdir -p /tmp/push-gate-test && cat > /tmp/push-gate-test/test.mjs <<'EOF'
import assert from "node:assert/strict";
import { createPushGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-inv-g2-2/bot.mjs";

const tokyo = { id: "u_8841", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
const at = (iso) => new Date(iso);
let n = 0;
const t = (name, fn) => { fn(); n++; console.log("ok -", name); };

t("quiet hours block late night local time (23:30 Tokyo = 14:30Z)", () => {
  const g = createPushGate();
  assert.deepEqual(g.attempt(tokyo, at("2026-10-22T14:30:00Z")), { allowed: false, reason: "quiet_hours" });
});
t("quiet window wraps midnight: 00:30 blocked, 06:59 blocked, 07:00 allowed", () => {
  const g = createPushGate();
  assert.equal(g.attempt(tokyo, at("2026-10-22T15:30:00Z")).reason, "quiet_hours"); // 00:30 JST
  assert.equal(g.attempt(tokyo, at("2026-10-21T21:59:00Z")).allowed, true);          // 06:59 JST? no: 21:59Z = 06:59 JST
});
t("boundary: 21:59 JST allowed, 22:00 JST blocked", () => {
  const g = createPushGate();
  assert.equal(g.attempt(tokyo, at("2026-10-22T12:59:00Z")).allowed, true);  // 21:59 JST
  assert.equal(g.attempt(tokyo, at("2026-10-22T13:00:00Z")).reason, "quiet_hours"); // 22:00 JST
});
t("daily cap counts per local calendar day, resets at local midnight", () => {
  const g = createPushGate();
  // 3 pushes on Tokyo day 2026-10-22 between 08:00 and 20:00 JST
  assert.equal(g.attempt(tokyo, at("2026-10-22T00:00:00Z")).allowed, true); // 09:00 JST
  assert.equal(g.attempt(tokyo, at("2026-10-22T05:00:00Z")).allowed, true); // 14:00 JST
  assert.equal(g.attempt(tokyo, at("2026-10-22T10:00:00Z")).allowed, true); // 19:00 JST
  assert.deepEqual(g.attempt(tokyo, at("2026-10-22T11:00:00Z")), { allowed: false, reason: "daily_cap_reached" }); // 20:00 JST
  // 00:10 JST next day: only 10 minutes after the last push, but a new local day
  assert.equal(g.attempt(tokyo, at("2026-10-22T15:10:00Z")).reason, "quiet_hours"); // 00:10 is quiet, so use 07:10
  assert.equal(g.attempt(tokyo, at("2026-10-22T22:10:00Z")).allowed, true); // 07:10 JST Oct 23
});
t("UTC-day boundary is not used: pushes at 23:00 JST and 07:30 JST next day are different local days", () => {
  const g = createPushGate();
  const cap1 = { ...tokyo, dailyCap: 1, quietStart: "02:00", quietEnd: "02:00" };
  assert.equal(g.attempt(cap1, at("2026-10-22T14:00:00Z")).allowed, true); // 23:00 JST Oct 22
  assert.equal(g.attempt(cap1, at("2026-10-22T22:30:00Z")).allowed, true); // 07:30 JST Oct 23
});
t("cap 0 blocks everything; quiet check wins when both apply", () => {
  const g = createPushGate();
  assert.equal(g.attempt({ ...tokyo, dailyCap: 0 }, at("2026-10-22T03:00:00Z")).reason, "daily_cap_reached");
  assert.equal(g.attempt({ ...tokyo, dailyCap: 0 }, at("2026-10-22T14:30:00Z")).reason, "quiet_hours");
});
t("blocked attempts do not count toward the cap", () => {
  const g = createPushGate();
  const cap1 = { ...tokyo, dailyCap: 1 };
  assert.equal(g.attempt(cap1, at("2026-10-22T14:30:00Z")).reason, "quiet_hours");
  assert.equal(g.attempt(cap1, at("2026-10-22T01:00:00Z")).allowed, true); // 10:00 JST
});
t("cap is read from each call (changes take effect immediately)", () => {
  const g = createPushGate();
  assert.equal(g.attempt({ ...tokyo, dailyCap: 1 }, at("2026-10-22T01:00:00Z")).allowed, true);
  assert.equal(g.attempt({ ...tokyo, dailyCap: 1 }, at("2026-10-22T02:00:00Z")).reason, "daily_cap_reached");
  assert.equal(g.attempt({ ...tokyo, dailyCap: 5 }, at("2026-10-22T02:00:00Z")).allowed, true);
});
t("users are independent; separate gates are independent", () => {
  const g = createPushGate();
  const a = { ...tokyo, id: "a", dailyCap: 1 };
  const b = { ...tokyo, id: "b", dailyCap: 1 };
  assert.equal(g.attempt(a, at("2026-10-22T01:00:00Z")).allowed, true);
  assert.equal(g.attempt(b, at("2026-10-22T01:00:00Z")).allowed, true);
  assert.equal(createPushGate().attempt(a, at("2026-10-22T01:30:00Z")).allowed, true);
});
t("DST zone: America/New_York, quiet 22:00-07:00 across DST start (2026-03-08)", () => {
  const g = createPushGate();
  const ny = { id: "ny", timeZone: "America/New_York", quietStart: "22:00", quietEnd: "07:00", dailyCap: 5 };
  assert.equal(g.attempt(ny, at("2026-03-08T02:30:00Z")).reason, "quiet_hours"); // 22:30 EST Mar 7
  assert.equal(g.attempt(ny, at("2026-03-08T11:00:00Z")).allowed, true);         // 07:00 EDT Mar 8
});
t("quietStart === quietEnd means no quiet period", () => {
  const g = createPushGate();
  assert.equal(g.attempt({ ...tokyo, quietStart: "00:00", quietEnd: "00:00" }, at("2026-10-22T14:30:00Z")).allowed, true);
});
t("non-wrapping window works (13:00-14:00)", () => {
  const g = createPushGate();
  const lunch = { ...tokyo, quietStart: "13:00", quietEnd: "14:00" };
  assert.equal(g.attempt(lunch, at("2026-10-22T04:30:00Z")).reason, "quiet_hours"); // 13:30 JST
  assert.equal(g.attempt(lunch, at("2026-10-22T05:00:00Z")).allowed, true);         // 14:00 JST
});
t("invalid inputs throw instead of silently allowing", () => {
  const g = createPushGate();
  assert.throws(() => g.attempt({ ...tokyo, timeZone: "Mars/Olympus" }, new Date()), RangeError);
  assert.throws(() => g.attempt({ ...tokyo, quietStart: "25:00" }, new Date()), TypeError);
  assert.throws(() => g.attempt({ ...tokyo, dailyCap: -1 }, new Date()), TypeError);
  assert.throws(() => g.attempt(tokyo, new Date("nope")), TypeError);
});
console.log(`\n${n} groups passed`);
EOF
